begin;
update public.cards set data = data || jsonb_build_object('back', 'On résout $n_A - a\,x_{\max} = 0$ et $n_B - b\,x_{\max} = 0$.<br><table style="border-collapse:collapse;margin:8px auto"><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center"></td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$a\,\mathrm{A}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$b\,\mathrm{B}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$c\,\mathrm{C}$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center">Initial</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_A$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_B$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$0$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center">En cours</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_A - a\,x$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_B - b\,x$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$c\,x$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center">Final</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_A - a\,x_{\max}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_B - b\,x_{\max}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$c\,x_{\max}$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0">Si limitant</td><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0">$x_{\max} = \dfrac{n_A}{a}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0">$x_{\max} = \dfrac{n_B}{b}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0"></td></tr></table>$x_{\max}$ est la **plus petite** valeur trouvée ; le réactif correspondant est le **limitant**.'::text, 'updatedAt', 1793569172401::bigint) where data->>'code' = '11ER-021' and not deleted;
update public.cards set data = data || jsonb_build_object('back', '1. Calculer les quantités initiales en mol.<br>2. Construire le tableau d''avancement.<br>3. Trouver $x_{\max}$ (plus petite valeur).<br>4. Remplacer $x_f$ par $x_{\max}$ dans la ligne « Final », pour chaque espèce.<table style="border-collapse:collapse;margin:8px auto"><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center"></td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$a\,\mathrm{A}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$b\,\mathrm{B}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$c\,\mathrm{C}$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center">Initial</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_A$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_B$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$0$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center">En cours</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_A - a\,x$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_B - b\,x$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$c\,x$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center">Final</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_A - a\,x_{\max}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$n_B - b\,x_{\max}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center">$c\,x_{\max}$</td></tr><tr><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0">Si limitant</td><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0">$x_{\max} = \dfrac{n_A}{a}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0">$x_{\max} = \dfrac{n_B}{b}$</td><td style="border:1px solid #999;padding:4px 8px;text-align:center;background:#fbe7b0"></td></tr></table>'::text, 'updatedAt', 1793569172401::bigint) where data->>'code' = '11ER-070' and not deleted;
commit;
select data->>'code' as code, data->>'back' like '%Si limitant%' as tableau from public.cards where data->>'code' in ('11ER-021','11ER-070') order by 1;
